def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = next((v for row in grid for v in row if v != 0), None)
    if marker is None:
        return out

    # Each marker on the top row is the tip of a downward-opening triangle.
    for apex in range(w):
        if grid[0][apex] != marker:
            continue
        for r in range(1, h):
            left, right = apex - r, apex + r
            for c in range(max(0, left + 1), min(w, right)):
                if grid[r][c] == 0:
                    out[r][c] = 2
    return out
